function check(input, actual, expected) {
  const nums = input[0];
  const n = nums.length / 2;
  if (!Array.isArray(actual) || actual.length !== n || !actual.every(Number.isInteger)) return false;
  // The smallest value of nums must be (smallest element of arr) - k, which fixes k.
  let smallest = Infinity;
  for (const v of nums) smallest = Math.min(smallest, v);
  let least = Infinity;
  for (const v of actual) least = Math.min(least, v);
  const k = least - smallest;
  if (k <= 0) return false;
  const made = [...actual.map(v => v - k), ...actual.map(v => v + k)].sort((a, b) => a - b);
  const given = [...nums].sort((a, b) => a - b);
  return made.every((v, i) => v === given[i]);
}

