function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 2000) return 'nums needs 2 to 2000 values.';
  if (nums.length % 2 !== 0) return 'nums needs an even number of values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each value is an integer from 1 to 10^9.';
  // The guarantee: some positive even gap pairs every value with one exactly that much larger.
  const sorted = [...nums].sort((a, b) => a - b);
  const tried = new Set();
  for (let j = 1; j <= sorted.length / 2; j++) {
    const gap = sorted[j] - sorted[0];
    if (gap === 0 || gap % 2 !== 0 || tried.has(gap)) continue;
    tried.add(gap);
    const used = new Array(sorted.length).fill(false);
    let high = 0, pairs = 0;
    for (let low = 0; low < sorted.length; low++) {
      if (used[low]) continue;
      high = Math.max(high, low + 1);
      while (high < sorted.length && (used[high] || sorted[high] < sorted[low] + gap)) high++;
      if (high === sorted.length || sorted[high] !== sorted[low] + gap) break;
      used[high] = true;
      pairs++;
    }
    if (pairs === sorted.length / 2) return null;
  }
  return 'No original array with a positive k can produce these values.';
}

