function recoverArray(nums) {
  // Try every way to choose which n values were the "minus k" side; the two sides,
  // each sorted, must then line up with one constant positive even difference.
  const n = nums.length / 2;
  for (let mask = 0; mask < 1 << nums.length; mask++) {
    const lower = [], higher = [];
    nums.forEach((v, i) => (mask >> i & 1 ? lower : higher).push(v));
    if (lower.length !== n) continue;
    lower.sort((a, b) => a - b);
    higher.sort((a, b) => a - b);
    const twice = higher[0] - lower[0];
    if (twice <= 0 || twice % 2 !== 0) continue;
    if (lower.every((v, i) => higher[i] - v === twice)) return lower.map(v => v + twice / 2);
  }
  return [];
}

