function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let n, k, arr;
  if (size === 'small') {
    n = pick(1, 5);
    k = pick(1, 4);
    arr = Array.from({ length: n }, () => pick(k + 1, k + 8));
  } else {
    n = 1000;
    const mode = pick(0, 2);
    if (mode === 0) {
      // Spread-out values with a large k.
      k = pick(1, 1e8);
      arr = Array.from({ length: n }, () => pick(k + 1, 1e9 - k));
    } else if (mode === 1) {
      // Dense values with many repeats and many candidate gaps.
      k = pick(1, 6);
      arr = Array.from({ length: n }, () => pick(k + 1, k + 40));
    } else {
      // An evenly spaced original array, so the values form long arithmetic runs.
      k = pick(1, 400000);
      arr = Array.from({ length: n }, (_, i) => k + 1 + i * 2 * k);
    }
  }
  const nums = [...arr.map(v => v - k), ...arr.map(v => v + k)];
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
